// Generates app/data/wmm2025.generated.ts from NOAA's World Magnetic Model 2025 coefficient file (WMM.COF).
//
//   node scripts/gen-wmm.mjs tests/fixtures/WMM2025.COF
//
// Source: NOAA/NCEI, https://www.ncei.noaa.gov/sites/default/files/2024-12/WMM2025COF.zip (WMM.COF, "2025.0  WMM-2025  11/13/2024").
// The WMM is a US/UK government work, free to use. The file holds numbers only. Never hand-edit the generated file.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const src = process.argv[2] ?? path.resolve(here, "../tests/fixtures/WMM2025.COF");
const lines = fs.readFileSync(src, "utf8").split(/\r?\n/);
const head = lines[0].trim().split(/\s+/);
const epoch = Number(head[0]);
const model = head[1];
const rows = [];
for (const l of lines.slice(1)) {
  const p = l.trim().split(/\s+/);
  if (p.length < 6 || p[0].startsWith("9999")) continue;
  rows.push(p.slice(0, 6).map(Number));
}
if (epoch !== 2025 || model !== "WMM-2025") throw new Error(`unexpected model header: ${lines[0]}`);
if (rows.length !== 90 || rows.some((r) => r.some((v) => !Number.isFinite(v)))) throw new Error(`expected 90 coefficient rows, got ${rows.length}`);

const out = `// GENERATED by scripts/gen-wmm.mjs from NOAA's WMM2025 coefficient file. Do not edit by hand; re-run the script.
// WMM-2025, epoch 2025.0 (file dated 11/13/2024). Each row: n, m, g, h, gdot, hdot (nT and nT per year). Numbers only.
export const WMM_MODEL = "WMM-2025";
export const WMM_EPOCH = ${epoch};
export const WMM_COEFFICIENTS: [number, number, number, number, number, number][] = [
${rows.map((r) => "  [" + r.join(", ") + "],").join("\n")}
];
`;
fs.writeFileSync(path.resolve(here, "../app/data/wmm2025.generated.ts"), out);
console.log(`wrote app/data/wmm2025.generated.ts (${rows.length} coefficient rows)`);
